//! A USB class driver's two functions, after BeginIO and AbortIO: what
//! usb.library calls a driver in DEVS:usb/ with when it offers it an
//! interface, and when that interface goes. Every class driver has them
//! (sdk/devices/usbclass.zig); the base is the driver's, io_Device of an
//! open request.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/usbclass_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const usb = @import("../libs/usb/usb.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "usbclass";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const USBClassBind = libraries.lvo(6);
    pub const USBClassUnbind = libraries.lvo(7);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const USBClassBind = *const fn (*UsbClassBase, *usb.USBBinding) callconv(.c) bool;
    pub const USBClassUnbind = *const fn (*UsbClassBase, *usb.USBBinding) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const UsbClassBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *UsbClassBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// An interface offered: true if the driver takes it - it has opened its
    /// pipes and filled a unit, `binding.unit` saying which - false if it
    /// declines and the next driver is asked. Called on the bus's process,
    /// which nothing else on the bus moves while it runs: decide quickly,
    /// and leave anything slow to the driver's own task. It may make control
    /// transfers on the device (DoUSBControl) and open pipes.
    pub fn USBClassBind(self: *UsbClassBase, binding: *usb.USBBinding) bool {
        return libraries.call(self, LVO.USBClassBind, Fn.USBClassBind, .{binding});
    }

    /// The interface is gone - the device was pulled, or the bus stops: every
    /// request the driver has outstanding on it answered, its pipes closed,
    /// its unit left without what was in it. Called on the bus's process.
    pub fn USBClassUnbind(self: *UsbClassBase, binding: *usb.USBBinding) void {
        return libraries.call(self, LVO.USBClassUnbind, Fn.USBClassUnbind, .{binding});
    }
};
